    - { name: "Streetwise", base: 35, per_level: 4, note: "+15%" }
    - { name: "Prowl", base: 35, per_level: 5, note: "+10%" }
    - { name: "Pick Locks", base: 45, per_level: 5, note: "+15%" }
    - { name: "Running", base: 0, per_level: 0 }
