    - { name: "Hand to Hand: Basic", base: 0, per_level: 0, note: "Can be changed to Expert at the cost of one related skill, or to Martial Arts or Assassin for two." }
  occ_related_skills:
    count: 6
    schedule: [{ level: 2, count: 2 }, { level: 5, count: 2 }, { level: 8, count: 1 }, { level: 12, count: 1 }]
